@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  /* Dynamic — dark theme, vibrant colors, pill-shaped components */
  --background: oklch(0 0 0);               /* pure black */
  --foreground: oklch(0.9463 0.0009 247.83);            /* rgb(236, 237, 238) */

  --card: oklch(0.2102 0.006 285.87);                  /* rgb(24, 24, 27) content1 */
  --card-foreground: oklch(0.9463 0.0009 247.83);

  --popover: oklch(0.2323 0.0058 285.94);
  --popover-foreground: oklch(0.9463 0.0009 247.83);

  --primary: oklch(0.5702 0.2106 257.94);             /* rgb(0, 111, 238) #006FEE */
  --primary-foreground: oklch(1 0 0);

  --secondary: oklch(0.2747 0.006 286);             /* rgb(39, 39, 42) neutral/default bg */
  --secondary-foreground: oklch(0.9463 0.0009 247.83);

  --muted: oklch(0.2747 0.006 286);
  --muted-foreground: oklch(0.7127 0.0128 286.07);      /* rgb(161, 161, 170) */

  --accent: oklch(0.5802 0.1895 304.14);               /* rgb(147, 83, 211) #9353D3 — Dynamic purple secondary */
  --accent-foreground: oklch(1 0 0);

  --destructive: oklch(0.6183 0.2417 11.15);          /* rgb(243, 18, 96) #F31260 */
  --destructive-foreground: oklch(1 0 0);

  /* Extended Dynamic semantic tokens */
  --success: oklch(0.7355 0.1945 150.78);              /* rgb(23, 201, 100) #17C964 */
  --success-foreground: oklch(1 0 0);

  --warning: oklch(0.7808 0.1583 72.25);               /* rgb(245, 165, 36) #F5A524 */
  --warning-foreground: oklch(0 0 0);

  --border: oklch(0.2948 0.0066 285.99);
  --input: oklch(0.2747 0.006 286);
  --ring: oklch(0.5702 0.2106 257.94);
  --radius: 0.75rem;                   /* 12px — Dynamic medium radius */
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: var(--font-inter), ui-sans-serif, system-ui, -apple-system,
      BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
}
